  'harness.compare.variantLabel': ["Name in the results (optional)", "Nombre en los resultados (opcional)", "Name in den Ergebnissen (optional)", "Nom dans les résultats (facultatif)", "Nome nei risultati (facoltativo)", "Nome nos resultados (opcional)", "结果中的名称（可选）"],
